import { z } from "zod"
import { messagingMessages } from "@/lib/messages/messaging"
import { MAX_MESSAGE_LENGTH } from "../types"

export const sendMessageSchema = z.object({
  conversationId: z.guid(),
  /** Generated by the client and reused on retry: the RPC is idempotent on it. */
  clientId: z.guid(),
  body: z
    .string()
    .trim()
    .min(1, messagingMessages.validation.empty)
    .max(MAX_MESSAGE_LENGTH, messagingMessages.validation.tooLong),
})
export type SendMessageInput = z.infer<typeof sendMessageSchema>

export const startConversationSchema = z.object({ userId: z.guid() })
export type StartConversationInput = z.infer<typeof startConversationSchema>

const timestampSchema = z.iso.datetime({ offset: true })

export const markConversationReadSchema = z.object({
  conversationId: z.guid(),
  /** Newest message the client has shown; omitted = everything up to now. */
  upTo: timestampSchema.optional(),
})
export type MarkConversationReadInput = z.infer<typeof markConversationReadSchema>

/** The RPC returns nothing under 2 chars; the cap keeps the ILIKE pattern small. */
export const searchMembersSchema = z.object({ query: z.string().trim().min(2).max(100) })
export type SearchMembersInput = z.infer<typeof searchMembersSchema>

/** A position in a thread: (created_at, id), the same order as the index. */
export const messageCursorSchema = z.object({ createdAt: timestampSchema, id: z.guid() })
export type MessageCursor = z.infer<typeof messageCursorSchema>

export const loadMessagesSchema = z.object({
  conversationId: z.guid(),
  /** "older": the page before the cursor. "newer": everything from the cursor on (catch-up after reconnect). */
  direction: z.enum(["older", "newer"]),
  cursor: messageCursorSchema,
})
export type LoadMessagesInput = z.infer<typeof loadMessagesSchema>
